_OPERATORS = ("**", "//", "+", "-", "*", "%", "(", ")")


def _tokenize(text: str) -> list:
    """Split into integers (``int``) and operator/parenthesis strings; spaces are skipped."""
    tokens = []
    i = 0
    while i < len(text):
        c = text[i]
        if c == " ":
            i += 1
        elif "0" <= c <= "9":
            j = i
            while j < len(text) and "0" <= text[j] <= "9":
                j += 1
            tokens.append(int(text[i:j]))
            i = j
        else:
            for op in _OPERATORS:
                if text.startswith(op, i):
                    tokens.append(op)
                    i += len(op)
                    break
            else:
                raise ValueError(f"unexpected character {c!r} in {text!r}")
    return tokens


class _Parser:
    """Recursive descent following Python's grammar: ``**`` takes a unary operand on its right."""

    def __init__(self, tokens: list):
        self.tokens = tokens
        self.pos = 0

    def peek(self):
        return self.tokens[self.pos] if self.pos < len(self.tokens) else None

    def take(self):
        token = self.peek()
        self.pos += 1
        return token

    def expr(self) -> int:
        value = self.term()
        while self.peek() in ("+", "-"):
            op = self.take()
            right = self.term()
            value = value + right if op == "+" else value - right
        return value

    def term(self) -> int:
        value = self.factor()
        while self.peek() in ("*", "//", "%"):
            op = self.take()
            right = self.factor()
            if op == "*":
                value *= right
            elif right == 0:
                raise ValueError("division or modulo by zero")
            elif op == "//":
                value //= right
            else:
                value %= right
        return value

    def factor(self) -> int:
        if self.peek() == "-":
            self.take()
            return -self.factor()
        if self.peek() == "+":
            self.take()
            return self.factor()
        return self.power()

    def power(self) -> int:
        base = self.atom()
        if self.peek() == "**":
            self.take()
            exponent = self.factor()
            if exponent < 0:
                raise ValueError("negative exponent gives a fraction, which is not supported")
            return base**exponent
        return base

